<script setup lang="ts">
import { computed, ref } from 'vue'
import { useLabStore } from '@/app/stores/lab'
import { CATALOG, MODULES } from '@/experiments/catalog'
import { visualLesson, MODEL_LABEL } from '@/experiments/visual/lessons'
import TopicPreview from '@/components/visual/TopicPreview.vue'
const lab = useLabStore(), search = ref(''), selected = ref('all'), model = ref('all')
const lessons = computed(()=>CATALOG.filter(e=>(selected.value==='all'||e.moduleId===selected.value) && `${e.id} ${e.title}`.toLowerCase().includes(search.value.toLowerCase().trim()) && (model.value==='all'||(visualLesson(e.id)?.model ?? 'engine')===model.value)))
</script>
<template>
  <div class="visual-home animated-catalog" :class="{'vl-light':!lab.darkMode}"><header class="vl-nav"><RouterLink to="/" class="vl-brand"><span class="vl-logo">h.</span> Hudi <b>Visual Lab</b></RouterLink><div class="vl-nav-actions"><RouterLink to="/">返回主题首页</RouterLink><button aria-label="切换深浅主题" @click="lab.toggleTheme()">{{ lab.darkMode ? '☀' : '☾' }}</button></div></header>
    <main class="catalog-main"><div class="catalog-heading"><div><span class="vl-eyebrow">80 个主题 · 9 个模块 · 先观察，再操作</span><h1>Hudi Lab 动画实验</h1><p>选一个你想弄懂的问题，从动画开始。</p></div><label class="catalog-search"><span>⌕</span><input v-model="search" type="search" placeholder="搜索主题、编号或关键词" aria-label="搜索动画实验"/></label></div>
      <nav class="catalog-filters" aria-label="模块筛选"><button :class="{active:selected==='all'}" @click="selected='all'">全部 <span>80</span></button><button v-for="module in MODULES" :key="module.id" :class="{active:selected===module.id}" @click="selected=module.id">{{ module.shortTitle }} <span>{{ CATALOG.filter(e=>e.moduleId===module.id).length }}</span></button></nav>
      <div class="catalog-status"><span>{{ lessons.length }} 个可播放主题</span><label>演示范围 <select v-model="model" aria-label="演示范围"><option value="all">全部类型</option><option value="engine">引擎驱动</option><option value="mixed">引擎 + 机制示意</option><option value="concept">机制示意</option></select></label></div>
      <div class="catalog-grid"><RouterLink v-for="entry in lessons" :key="entry.id" :to="`/experiment/${entry.id}`" class="catalog-card"><div class="catalog-card-meta"><span>{{ entry.id }} · {{ MODULES.find(m=>m.id===entry.moduleId)?.shortTitle }}</span><span>{{ entry.id==='B02'||entry.id==='B03' ? '双路径对比' : MODEL_LABEL[visualLesson(entry.id)!.model] }}</span></div><TopicPreview :kind="entry.id==='B02'||entry.id==='B03' ? 'compare' : visualLesson(entry.id)!.kind"/><h2>{{ entry.title }}</h2><div class="catalog-card-bottom"><span>{{ entry.supportState==='unverified'||entry.evidenceLevel==='E0' ? 'r26 待验证' : '教学模型' }}</span><span>开始观察 →</span></div></RouterLink></div>
      <div v-if="!lessons.length" class="catalog-empty"><p>没有找到匹配的动画。</p><button @click="search='';selected='all';model='all'">清除筛选</button></div>
      <p class="catalog-footnote">引擎驱动展示本地模拟结果；机制示意展示组件关系与处理关口，未执行真实集群服务。点击实验中的范围标签可查看边界。</p>
    </main><footer class="vl-footer"><span>HUAWEI MRS r26 · 纯浏览器模拟</span><span>看动画 → 亲手操作 → 解释 → 代码</span></footer>
  </div>
</template>
